#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Node {
    long val;
    struct Node *left;
    struct Node *right;
} Node;

static int printed = 0; // flag for spacing in output

static void insert(Node **root, long v) {
    while (*root) {
        if (v < (*root)->val) {
            root = &(*root)->left;
        } else if (v > (*root)->val) {
            root = &(*root)->right;
        } else { // duplicate goes to the right subtree
            root = &(*root)->right;
        }
    }
    *root = malloc(sizeof(Node));
    if (!*root) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    (*root)->val = v;
    (*root)->left = NULL;
    (*root)->right = NULL;
}

static void print_value(long v) {
    if (printed) putchar(' ');
    printf("%ld", v);
    printed = 1;
}

static void inorder(Node *n) {
    if (!n) return;
    inorder(n->left);
    print_value(n->val);
    inorder(n->right);
}

static void preorder(Node *n) {
    if (!n) return;
    print_value(n->val);
    preorder(n->left);
    preorder(n->right);
}

static void postorder(Node *n) {
    if (!n) return;
    postorder(n->left);
    postorder(n->right);
    print_value(n->val);
}

static void free_tree(Node *n) {
    if (!n) return;
    free_tree(n->left);
    free_tree(n->right);
    free(n);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        puts("INVALID_MODE");
        return 0;
    }
    const char *mode = argv[1];
    Node *root = NULL;
    for (int i = 2; i < argc; ++i) {
        long v = strtol(argv[i], NULL, 10);
        insert(&root, v);
    }
    if (strcmp(mode, "in") == 0) {
        if (!root) {
            puts("EMPTY");
        } else {
            inorder(root);
        }
    } else if (strcmp(mode, "pre") == 0) {
        if (!root) {
            puts("EMPTY");
        } else {
            preorder(root);
        }
    } else if (strcmp(mode, "post") == 0) {
        if (!root) {
            puts("EMPTY");
        } else {
            postorder(root);
        }
    } else {
        puts("INVALID_MODE");
        return 0;
    }
    putchar('\n');
    free_tree(root);
    return 0;
}
